line = open("/etc/data-asset/credentials/ods_8_216").readline().strip()
u, _, p = line.partition(":")
conn = oracledb.connect(user=u, password=p, dsn="10.10.8.216:1521/orcl", tcp_connect_timeout=20)
conn.call_timeout = 60000
cur = conn.cursor()
print("== ODS 活源列对齐（ALL_TAB_COLUMNS vs 目标列）==")
for tname, tcols in TARGETS.items():
    view = "V_" + tname
    cur.execute(
        "SELECT COLUMN_NAME, DATA_TYPE FROM ALL_TAB_COLUMNS "
        "WHERE OWNER='ODS' AND TABLE_NAME=:v", {"v": view})
    src = {r[0].upper(): r[1] for r in cur.fetchall()}
    cur.execute(
        "SELECT COUNT(*) FROM ALL_OBJECTS WHERE OWNER='ODS' AND OBJECT_NAME=:v "
        "AND OBJECT_TYPE='VIEW'", {"v": view})
    is_view = cur.fetchone()[0] == 1
    tset = set(tcols) - {"SYSTEM_TIME"}
    gap = sorted(tset - set(src))
    print(f"{tname}: view={is_view} 目标{len(tset)}列 gap={gap if gap else 'NONE'} "
          f"DATETIME_type={src.get('DATETIME','?')} 视图列数={len(src)}")
conn.close()
print("== 探查结束 ==")
